1	package main
2	
3	import (
4		"flag"
5		"fmt"
6		"io"
7		"net/netip"
8		"regexp"
9		"strings"
10		"time"
11	
12		"github.com/anthnel/devdesk/internal/nexusbench"
13	)
14	
15	// Defaults of the flags that are not a NEXUS_BENCH_* parameter.
16	const (
17		loopbackHost = "127.0.0.1"
18		maxHostLen   = 253
19	)
20	
21	var (
22		// hostName is a DNS name: letters, digits, '.' and '-', no port, no path,
23		// no credentials, no whitespace.
24		hostName = regexp.MustCompile(`^[A-Za-z0-9]([A-Za-z0-9.-]*[A-Za-z0-9])?$`)
25		// ipv6Zone is the zone of a link-local address ("eth0" in fe80::1%eth0).
26		ipv6Zone = regexp.MustCompile(`^[A-Za-z0-9._-]+$`)
27	)
28	
29	// flagKind is the type of a flag, which decides how it is registered and how
30	// its value is handed to nexusbench.FromEnv.
31	type flagKind int
32	
33	const (
34		kindString flagKind = iota
35		kindInt
36		kindDuration
37		kindBool
38		// kindConsent is a boolean whose true is the exact word "yes", the only
39		// value nexusbench accepts for NEXUS_BENCH_ACCEPT_EULA.
40		kindConsent
41	)
42	
43	// paramFlag is one flag that stands for one NEXUS_BENCH_* variable.
44	type paramFlag struct {
45		name  string
46		env   string
47		kind  flagKind
48		usage string
49	}
50	
51	// commonFlags are accepted by every subcommand.
52	func commonFlags() []paramFlag {
53		d := nexusbench.Defaults()
54		return []paramFlag{
55			{"context", "NEXUS_BENCH_CONTEXT", kindString, "kubectl context of the cluster (default " + d.Context + ")"},
56			{"namespace", "NEXUS_BENCH_NAMESPACE", kindString, "namespace of the bench, which down deletes (default " + d.Namespace + ")"},
57			{"http-nodeport", "NEXUS_BENCH_HTTP_NODEPORT", kindInt, fmt.Sprintf("NodePort of the REST API and the UI (default %d)", d.HTTPNodePort)},
58			{"docker-nodeport", "NEXUS_BENCH_DOCKER_NODEPORT", kindInt, fmt.Sprintf("NodePort of the Docker connector (default %d)", d.DockerNodePort)},
59			{"cpu-request", "NEXUS_BENCH_CPU_REQUEST", kindString, "CPU request (default " + d.CPURequest + ")"},
60			{"cpu-limit", "NEXUS_BENCH_CPU_LIMIT", kindString, "CPU limit (default " + d.CPULimit + ")"},
61			{"memory-request", "NEXUS_BENCH_MEMORY_REQUEST", kindString, "memory request (default " + d.MemoryRequest + ")"},
62			{"memory-limit", "NEXUS_BENCH_MEMORY_LIMIT", kindString, "memory limit (default " + d.MemoryLimit + ")"},
63			{"storage-size", "NEXUS_BENCH_STORAGE_SIZE", kindString, "size of the data volume (default " + d.StorageSize + ")"},
64			{"jvm-opts", "NEXUS_BENCH_JVM_OPTS", kindString, "JVM options of Nexus (default " + d.JVMOpts + ")"},
65			{"image", "NEXUS_BENCH_IMAGE", kindString, "Nexus image, without the tag (default " + d.Image + ")"},
66			{"image-tag", "NEXUS_BENCH_IMAGE_TAG", kindString, "Nexus image tag (default " + d.ImageTag + ")"},
67			{"upstream-image", "NEXUS_BENCH_UPSTREAM_IMAGE", kindString, "image of the bench upstream registry, without the tag (default " + d.UpstreamImage + ")"},
68			{"upstream-image-tag", "NEXUS_BENCH_UPSTREAM_IMAGE_TAG", kindString, "tag of the bench upstream registry image (default " + d.UpstreamImageTag + ")"},
69			{"upstream-url", "NEXUS_BENCH_UPSTREAM_URL", kindString, "upstream of the proxy repository (default http://bench-upstream.<namespace>.svc.cluster.local:5000)"},
70			{"anonymous", "NEXUS_BENCH_ANONYMOUS", kindBool, "enable anonymous access, --anonymous=false to disable (default true)"},
71			{"hosts", "NEXUS_BENCH_HOSTS", kindString, "comma-separated hosts the NodePorts are tried on (default 127.0.0.1 and the node address)"},
72			{"timeout", "NEXUS_BENCH_TIMEOUT", kindDuration, "how long up waits for Nexus, and how long the seed may run (default " + d.Timeout.String() + ")"},
73			{"delete-timeout", "NEXUS_BENCH_DELETE_TIMEOUT", kindDuration, "how long down waits for the namespace to go (default " + d.DeleteTimeout.String() + ")"},
74			{"secrets", "NEXUS_BENCH_SECRETS", kindString, "secrets file, outside the repository (default under $XDG_STATE_HOME/devdesk/nexus-bench)"},
75			{"descriptor", "NEXUS_BENCH_DESCRIPTOR", kindString, "descriptor file (default internal/nexusbench/descriptor.json)"},
76		}
77	}
78	
79	// provisionFlags are accepted by the subcommands that provision Nexus.
80	func provisionFlags() []paramFlag {
81		return []paramFlag{
82			{"accept-eula", "NEXUS_BENCH_ACCEPT_EULA", kindConsent, "accept the Nexus Community Edition EULA on your behalf: read it first (default false; the variable counts only as the exact value yes)"},
83		}
84	}
85	
86	// restHostFlag names the flag that picks the host the admin credentials are sent to.
87	const restHostFlag = "rest-host"
88	
89	// flagSet is the flags of one subcommand.
90	type flagSet struct {
91		fs       *flag.FlagSet
92		specs    map[string]paramFlag
93		restHost *string
94	}
95	
96	// newFlagSet registers the flags of a subcommand. It prints nothing by itself:
97	// the caller reports a parse error on stderr and the help on stdout.
98	func newFlagSet(name string) *flagSet {
99		// up and provision provision Nexus (EULA); they and seed send the admin
100		// credentials to the REST API (REST host).
101		provisions := name == "up" || name == "provision"
102		reachesREST := provisions || name == "seed"
103		fs := flag.NewFlagSet("nexus-bench "+name, flag.ContinueOnError)
104		fs.SetOutput(io.Discard)
105		fs.Usage = func() {}
106		set := &flagSet{fs: fs, specs: map[string]paramFlag{}}
107		specs := commonFlags()
108		if provisions {
109			specs = append(specs, provisionFlags()...)
110		}
111		for _, spec := range specs {
112			set.specs[spec.name] = spec
113			switch spec.kind {
114			case kindString:
115				fs.String(spec.name, "", spec.usage)
116			case kindInt:
117				fs.Int(spec.name, 0, spec.usage)
118			case kindDuration:
119				fs.Duration(spec.name, time.Duration(0), spec.usage)
120			case kindBool, kindConsent:
121				fs.Bool(spec.name, false, spec.usage)
122			}
123		}
124		switch {
125		case name == "seed":
126			// seed refuses another host (main.go): its credentials and its images
127			// always go through the loopback.
128			set.restHost = fs.String(restHostFlag, "", "loopback address the REST API is reached on (default "+loopbackHost+"); seed accepts a loopback address only, because its images and the admin credentials always go through "+loopbackHost)
129		case reachesREST:
130			set.restHost = fs.String(restHostFlag, "", "host the REST API is reached on, and so the host the admin credentials are sent to (default "+loopbackHost+"); another host sends them in clear text. It concerns the REST API only: the images always go through "+loopbackHost)
131		}
132		return set
133	}
134	
135	// parse reads args. It returns flag.ErrHelp for -h and --help, and an error for
136	// an unknown flag, a value of the wrong type or an argument that is not a flag.
137	func (s *flagSet) parse(args []string) error {
138		if err := s.fs.Parse(args); err != nil {
139			return err
140		}
141		if s.fs.NArg() > 0 {
142			return fmt.Errorf("unexpected argument %q", s.fs.Arg(0))
143		}
144		return nil
145	}
146	
147	// printHelp writes the flags and their default to w.
148	func (s *flagSet) printHelp(w io.Writer) {
149		s.fs.SetOutput(w)
150		s.fs.PrintDefaults()
151		s.fs.SetOutput(io.Discard)
152	}
153	
154	// overlay returns getenv with every flag that was given laid over its
155	// NEXUS_BENCH_* variable: nexusbench.FromEnv then applies "flag, then variable,
156	// then default" in one place, with the same parsing and the same follow-the-
157	// namespace rule for the upstream URL.
158	func (s *flagSet) overlay(getenv func(string) string) func(string) string {
159		given := map[string]string{}
160		s.fs.Visit(func(f *flag.Flag) {
161			spec, ok := s.specs[f.Name]
162			if !ok {
163				return
164			}
165			value := f.Value.String()
166			if spec.kind == kindConsent {
167				value = map[bool]string{true: "yes", false: "no"}[value == "true"]
168			}
169			given[spec.env] = value
170		})
171		return func(name string) string {
172			if v, ok := given[name]; ok {
173				return v
174			}
175			return getenv(name)
176		}
177	}
178	
179	// restHostGiven returns the --rest-host value and whether it was set.
180	func (s *flagSet) restHostGiven() (string, bool) {
181		if s.restHost == nil {
182			return "", false
183		}
184		given := false
185		s.fs.Visit(func(f *flag.Flag) {
186			if f.Name == restHostFlag {
187				given = true
188			}
189		})
190		return *s.restHost, given
191	}
192	
193	// resolveParams returns the validated parameters of a run: defaults, then the
194	// NEXUS_BENCH_* variables, then the flags.
195	func (s *flagSet) resolveParams(getenv func(string) string) (nexusbench.Params, error) {
196		p, err := nexusbench.FromEnv(nexusbench.Defaults(), s.overlay(getenv))
197		if err != nil {
198			return p, err
199		}
200		return p, p.Validate()
201	}
202	
203	// validateRESTHost refuses what is not a host name or an IP address: a port, a
204	// path, a scheme, credentials or whitespace would change where the admin
205	// credentials go.
206	func validateRESTHost(host string) error {
207		if host == "" || len(host) > maxHostLen {
208			return fmt.Errorf("--%s: %q is not a host name or an IP address", restHostFlag, host)
209		}
210		if addr, ok := hostAddress(host); ok {
211			if zone := addr.Zone(); zone != "" && !ipv6Zone.MatchString(zone) {
212				return fmt.Errorf("--%s: %q has an unusable IPv6 zone", restHostFlag, host)
213			}
214			return nil
215		}
216		if !hostName.MatchString(host) {
217			return fmt.Errorf("--%s: %q is not a host name or an IP address (no port, scheme, path or credentials)", restHostFlag, host)
218		}
219		return nil
220	}
221	
222	// hostAddress parses host as an IP address, with or without the brackets of an
223	// IPv6 literal.
224	func hostAddress(host string) (netip.Addr, bool) {
225		if len(host) > 1 && strings.HasPrefix(host, "[") && strings.HasSuffix(host, "]") {
226			host = host[1 : len(host)-1]
227		}
228		addr, err := netip.ParseAddr(host)
229		return addr, err == nil
230	}
231	
232	// isLoopbackHost tells whether host stays on this machine.
233	func isLoopbackHost(host string) bool {
234		if strings.EqualFold(host, "localhost") {
235			return true
236		}
237		addr, ok := hostAddress(host)
238		return ok && addr.Unmap().IsLoopback()
239	}
