12	// render prints the manifests. It builds no dependency: it contacts nothing.
13	func (s *session) render() int {
14		out, err := nexusbench.Render(s.p)
15		if err != nil {
16			return s.fail(err)
17		}
18		if _, err := s.stdout.Write(out); err != nil {
19			return s.fail(err)
20		}
21		return exitOK
22	}
23	
24	// open resolves the secrets path and builds the runner and the store, in that
25	// order, before anything touches the cluster. Both are refused here when they
26	// cannot work: kubectl missing, a secrets path that git does not ignore.
27	func (s *session) open() (nexusbench.Runner, nexusbench.SecretStore, error) {
28		if s.p.SecretsPath == "" {
29			path, err := nexusbench.DefaultSecretsPath(s.p.Context, s.p.Namespace, s.getenv)
30			if err != nil {
31				return nil, nil, err
32			}
33			s.p.SecretsPath = path
34		}
35		runner, err := s.d.newRunner(s.p.Context)
36		if err != nil {
37			return nil, nil, err
38		}
39		store, err := s.d.newStore(s.p.SecretsPath)
40		if err != nil {
41			return nil, nil, err
42		}
43		return runner, store, nil
44	}
45	
46	// doors are the two doors the seed goes through besides kubectl: the
47	// port-forward to the upstream and the image copier.
48	type doors struct {
49		forwarder nexusbench.PortForwarder
50		copier    nexusbench.ImageCopier
51	}
52	
53	// openDoors builds the doors of the seed, the forwarder first. They are built
54	// before anything touches the cluster: a host without skopeo is refused here,
55	// not after the deployment.
56	func (s *session) openDoors() (doors, error) {
57		forwarder, err := s.d.newForwarder(s.p.Context)
58		if err != nil {
59			return doors{}, err
60		}
61		copier, err := s.d.newCopier()
62		if err != nil {
63			return doors{}, err
64		}
65		return doors{forwarder: forwarder, copier: copier}, nil
66	}
67	
68	// runSeed runs Seed with a context that ends after Params.Timeout, counted from
69	// now, so that a copy over a port-forward that hangs does not hang the command.
70	// A seed that outlasts it is a failure with its own message; a cancelled run
71	// keeps the plain cancellation.
72	func (s *session) runSeed(runner nexusbench.Runner, store nexusbench.SecretStore, d doors) (nexusbench.SeedResult, error) {
73		ctx, cancel := s.ctx, context.CancelFunc(func() {})
74		if s.p.Timeout > 0 {
75			ctx, cancel = context.WithTimeout(s.ctx, s.p.Timeout)
76		}
77		defer cancel()
78		deps := nexusbench.SeedDeps{Runner: runner, Forwarder: d.forwarder, Copier: d.copier, Clock: s.d.clock, Store: store}
79		res, err := s.d.seed(ctx, deps, s.restURL(), s.p, s.stdout)
80		if err != nil && ctx.Err() != nil && s.ctx.Err() == nil {
81			return nexusbench.SeedResult{}, &nexusbench.BenchError{
82				Kind:  nexusbench.Deadline,
83				Cause: fmt.Sprintf("the seed did not finish within %s", s.p.Timeout),
84				Check: "raise --timeout (NEXUS_BENCH_TIMEOUT) and run nexus-bench seed again: the images already copied are kept",
85				Err:   err,
86			}
87		}
88		return res, err
89	}
90	
91	// up deploys the bench and the upstream, provisions Nexus, seeds the data set
92	// and only then writes the descriptor (D-J). Deploy runs the preflight of up
93	// itself. An upstream URL the bench did not deploy is left alone: nothing is
94	// scaled or seeded, and the data set is described as empty.
95	func (s *session) up() int {
96		runner, store, err := s.open()
97		if err != nil {
98			return s.fail(err)
99		}
100		seeds := s.p.UpstreamIsBench()
101		var d doors
102		if seeds {
103			if d, err = s.openDoors(); err != nil {
104				return s.fail(err)
105			}
106		}
107		s.warnIfClearText()
108		deployed, err := s.d.deploy(s.ctx, runner, s.d.newProber(), s.d.clock, s.p, s.stdout)
109		if err != nil {
110			return s.fail(err)
111		}
112		if seeds {
113			if err := s.d.ensureUpstream(s.ctx, runner, s.d.clock, s.p, s.stdout); err != nil {
114				return s.fail(err)
115			}
116		}
117		provisioned, err := s.d.provision(s.ctx, s.restURL(), s.d.newInitial(runner, s.p.Namespace), store, s.p, s.stdout)
118		if err != nil {
119			return s.fail(err)
120		}
121		var seeded nexusbench.SeedResult
122		if seeds {
123			if seeded, err = s.runSeed(runner, store, d); err != nil {
124				return s.fail(err)
125			}
126		} else {
127			_, _ = fmt.Fprintln(s.stdout, "seed: skipped, NEXUS_BENCH_UPSTREAM_URL points at an upstream the bench did not deploy, so there is nothing to fill")
128		}
129		return s.writeDescriptor(deployed, provisioned, seeded)
130	}
131	
132	// provision provisions a bench that is already running.
133	func (s *session) provision() int {
134		runner, store, err := s.open()
135		if err != nil {
136			return s.fail(err)
137		}
138		s.warnIfClearText()
139		pre, err := s.d.preflight(s.ctx, runner, s.p, nexusbench.OpProvision)
140		if err != nil {
141			return s.fail(err)
142		}
143		provisioned, err := s.d.provision(s.ctx, s.restURL(), s.d.newInitial(runner, s.p.Namespace), store, s.p, s.stdout)
144		if err != nil {
145			return s.fail(err)
146		}
147		return s.writeDescriptor(nexusbench.DeployResult{NodeIP: pre.NodeIP}, provisioned, s.keptDataset())
148	}
149	
150	// keptDataset returns the data set of the code when the descriptor on disk is the
151	// descriptor of the same bench (namespace, context and upstream URL unchanged) and
152	// lists exactly that data set: the data set is fixed in the code, so what the file
153	// holds is compared to it and never copied. A file that disagrees, or is of another
154	// bench, counts as no data set, and the command says so. A descriptor that cannot
155	// be read (none, or schema 1), or that lists no image, has nothing to keep.
156	func (s *session) keptDataset() nexusbench.SeedResult {
157		prev, err := nexusbench.LoadDescriptor(s.descriptorPath())
158		if err != nil || len(prev.Dataset) == 0 {
159			return nexusbench.SeedResult{}
160		}
161		code := nexusbench.SeedResult{Images: nexusbench.Dataset()}
162		want := nexusbench.BuildDescriptor(s.p, nexusbench.DeployResult{}, nexusbench.ProvisionResult{}, code).Dataset
163		if prev.Namespace == s.p.Namespace && prev.KubeContext == s.p.Context && prev.Upstream.URL == s.p.UpstreamURL &&
164			reflect.DeepEqual(prev.Dataset, want) {
165			return code
166		}
167		line := "provision: the descriptor now lists no data set"
168		if s.p.UpstreamIsBench() {
169			line += "; run mise run nexus-bench:seed"
170		}
171		_, _ = fmt.Fprintln(s.stdout, line)
172		return nexusbench.SeedResult{}
173	}
174	
175	// seed puts the data set in a bench that up already provisioned, then writes the
176	// descriptor again. Seed has no data of its own about Nexus: the version, the
177	// edition, the EULA consent and the hosts (and so the URLs that depend on them)
178	// come from the descriptor of the previous run, which is read before anything is
179	// copied. The preflight of a seed does not read the node, so it has no address to
180	// give.
181	func (s *session) seed() int {
182		runner, store, err := s.open()
183		if err != nil {
184			return s.fail(err)
185		}
186		d, err := s.openDoors()
187		if err != nil {
188			return s.fail(err)
189		}
190		s.warnIfClearText()
191		prev, err := s.previousDescriptor()
192		if err != nil {
193			return s.fail(err)
194		}
195		if _, err := s.d.preflight(s.ctx, runner, s.p, nexusbench.OpSeed); err != nil {
196			return s.fail(err)
197		}
198		seeded, err := s.runSeed(runner, store, d)
199		if err != nil {
200			return s.fail(err)
201		}
202		provisioned := nexusbench.ProvisionResult{NexusVersion: prev.NexusVersion, Edition: prev.Edition, EULAAccepted: prev.EULAAccepted}
203		return s.writeDescriptor(nexusbench.DeployResult{ReachableHosts: prev.Hosts}, provisioned, seeded)
204	}
205	
206	// previousDescriptor reads the descriptor of the previous run. Without a readable
207	// descriptor of schema 2 (missing, schema 1, not JSON), or with the descriptor of
208	// another bench (namespace or context), the bench was not provisioned by this
209	// build for these parameters, and the answer is to run up.
210	func (s *session) previousDescriptor() (nexusbench.Descriptor, error) {
211		path := s.descriptorPath()
212		prev, err := nexusbench.LoadDescriptor(path)
213		var be *nexusbench.BenchError
214		switch {
215		case err == nil:
216		case errors.As(err, &be):
217			return prev, err
218		default:
219			return prev, &nexusbench.BenchError{
220				Kind:  nexusbench.Unclassified,
221				Cause: "there is no readable descriptor of a provisioned bench (" + err.Error() + ")",
222				Check: "run `mise run nexus-bench:up` first: the seed completes the descriptor that up writes",
223				Err:   err,
224			}
225		}
226		if prev.Namespace != s.p.Namespace || prev.KubeContext != s.p.Context {
227			return prev, &nexusbench.BenchError{
228				Kind:  nexusbench.Unclassified,
229				Cause: fmt.Sprintf("the descriptor %s describes namespace %q on context %q, not namespace %q on context %q", path, prev.Namespace, prev.KubeContext, s.p.Namespace, s.p.Context),
230				Check: "run `mise run nexus-bench:up` for this bench first: the seed completes the descriptor that up writes",
231			}
232		}
233		if err := nexusbench.ValidateDescriptorHosts(prev.Hosts); err != nil {
234			return prev, &nexusbench.BenchError{
235				Kind:  nexusbench.Unclassified,
236				Cause: fmt.Sprintf("the descriptor %s cannot be trusted: %s", path, err),
237				Check: "run `mise run nexus-bench:up` for this bench first: it writes the descriptor again",
238			}
239		}
240		return prev, nil
241	}
242	
243	// down deletes the bench namespace. The descriptor is left alone: it is the
244	// versioned description of the bench, not part of one instance.
245	func (s *session) down() int {
246		runner, store, err := s.open()
247		if err != nil {
248			return s.fail(err)
249		}
250		if err := s.d.destroy(s.ctx, runner, s.d.clock, store, s.p, s.stdout); err != nil {
251			return s.fail(err)
252		}
253		return exitOK
254	}
255	
256	// descriptorPath is where the descriptor is read and written.
257	func (s *session) descriptorPath() string {
258		if s.p.DescriptorPath != "" {
259			return s.p.DescriptorPath
260		}
261		return nexusbench.DescriptorPath()
262	}
263	
264	// writeDescriptor writes the descriptor of a bench that was provisioned and, for
265	// up and seed, seeded. It is called after a step that succeeded only: a partial
266	// result is never described.
267	func (s *session) writeDescriptor(deployed nexusbench.DeployResult, provisioned nexusbench.ProvisionResult, seeded nexusbench.SeedResult) int {
268		path := s.descriptorPath()
269		if err := nexusbench.WriteDescriptor(path, nexusbench.BuildDescriptor(s.p, deployed, provisioned, seeded)); err != nil {
270			return s.fail(err)
271		}
272		_, _ = fmt.Fprintf(s.stdout, "nexus-bench: descriptor written to %s\n", path)
273		if !describesDefaultBench(s.p) {
274			s.warn("descriptor.json now describes a non-default bench; do not commit it")
275		}
276		return exitOK
277	}
278	
279	// describesDefaultBench tells whether p is the bench the versioned descriptor
280	// describes. The timeouts, the paths and the EULA consent do not change what
281	// the bench is, so they are left out.
282	func describesDefaultBench(p nexusbench.Params) bool {
283		normalize := func(p nexusbench.Params) nexusbench.Params {
284			p.Timeout, p.DeleteTimeout = 0, 0
285			p.SecretsPath, p.DescriptorPath = "", ""
286			p.AcceptEULA = false
287			if len(p.Hosts) == 0 {
288				p.Hosts = nil
289			}
290			return p
291		}
292		return reflect.DeepEqual(normalize(p), normalize(nexusbench.Defaults()))
293	}
