50	// clusterEvents keeps what touches the cluster, in order: the preflights and
51	// the library calls. The constructors (newRunner, newStore, ...) are left out.
52	func (h *harness) clusterEvents() []string {
53		var out []string
54		for _, e := range h.eventList() {
55			switch {
56			case strings.HasPrefix(e, "preflight:"), e == "deploy", e == "ensureUpstream", e == "provision", e == "seed", e == "destroy":
57				out = append(out, e)
58			}
59		}
60		return out
61	}
