88	// writePreviousDescriptorFor is writePreviousDescriptor for a bench whose
89	// parameters are the defaults changed by mod. The UpstreamURL follows the
90	// namespace, as the command does.
91	func (h *harness) writePreviousDescriptorFor(mod func(*nexusbench.Params)) []byte {
92		h.t.Helper()
93		p := nexusbench.Defaults()
94		if mod != nil {
95			mod(&p)
96			p.UpstreamURL = "http://bench-upstream." + p.Namespace + ".svc.cluster.local:5000"
97		}
98		return writeDescriptorAt(h.t, h.descriptor, p, previousDeployment, previousProvisioning, nexusbench.SeedResult{})
99	}
