113	func TestSeedRunsPreflightThenSeedThenWritesTheDescriptor(t *testing.T) {
114		h := newHarness(t)
115		seedParams := func(p *nexusbench.Params) { p.Context, p.Namespace, p.HTTPNodePort = "ctx-seed", "nb-seed", 31001 }
116		previous := h.writePreviousDescriptorFor(seedParams)
117		code, stdout, stderr := h.run("seed", "--context", "ctx-seed", "--namespace", "nb-seed", "--http-nodeport", "31001")
118		if code != 0 {
119			t.Fatalf("exit code = %d\nstdout: %s\nstderr: %s", code, stdout, stderr)
120		}
121	
122		// The doors are built before the cluster is touched; then preflight, Seed.
123		if got, want := h.clusterEvents(), []string{"preflight:OpSeed", "seed"}; !slices.Equal(got, want) {
124			t.Fatalf("cluster events = %v, want %v (all: %v)", got, want, h.eventList())
125		}
126		for _, e := range []string{"newRunner", "newStore", "newForwarder", "newCopier"} {
127			if !h.before(e, "preflight:OpSeed") {
128				t.Errorf("%s must happen before the preflight, events: %v", e, h.eventList())
129			}
130		}
131		for _, e := range []string{"deploy", "provision", "ensureUpstream", "destroy", "newInitial"} {
132			if h.has(e) {
133				t.Errorf("seed called %s, events: %v", e, h.eventList())
134			}
135		}
136		if len(h.preflightOps) != 1 || h.preflightOps[0] != nexusbench.OpSeed {
137			t.Errorf("preflight ops = %v, want [OpSeed]", h.preflightOps)
138		}
139		if h.preflightRunner != nexusbench.Runner(h.runner) {
140			t.Error("the preflight was not given the runner of the deps")
141		}
142		if !reflect.DeepEqual(h.newForwarderContexts, []string{"ctx-seed"}) {
143			t.Errorf("newForwarder contexts = %v, want [ctx-seed]", h.newForwarderContexts)
144		}
145	
146		// What Seed was given: the doors of the deps and nothing else.
147		d := h.seedDeps
148		if d.Runner != nexusbench.Runner(h.runner) || d.Forwarder != nexusbench.PortForwarder(h.forward) ||
149			d.Copier != nexusbench.ImageCopier(h.copier) || d.Clock != nexusbench.Clock(h.clock) || d.Store != nexusbench.SecretStore(h.store) {
150			t.Errorf("SeedDeps = %+v, want the runner, forwarder, copier, clock and store of the deps", d)
151		}
152		if want := "http://127.0.0.1:31001"; h.seedURL != want {
153			t.Errorf("Seed base URL = %q, want %q", h.seedURL, want)
154		}
155		if h.seedParams.Namespace != "nb-seed" || h.seedParams.Context != "ctx-seed" || h.seedParams.HTTPNodePort != 31001 {
156			t.Errorf("Seed params = %+v", h.seedParams)
157		}
158		if !h.descriptorSeenAtSeed {
159			t.Error("the descriptor of the previous run should still be there while Seed runs")
160		}
161	
162		// The descriptor: the previous provisioning, the previous hosts (the
163		// preflight of a seed does not read the node, so it has no NodeIP to give),
164		// the data set Seed returned.
165		if h.preflightRes.NodeIP == "" {
166			t.Fatal("test setup: the preflight of the harness has a node IP, the seed must not need it")
167		}
168		p := nexusbench.Defaults()
169		seedParams(&p)
170		p.UpstreamURL = "http://bench-upstream.nb-seed.svc.cluster.local:5000"
171		got, err := os.ReadFile(h.descriptor)
172		if err != nil {
173			t.Fatalf("no descriptor: %v", err)
174		}
175		want := wantDescriptorBytesWith(t, p, previousDeployment, previousProvisioning, h.seedRes)
176		if !bytes.Equal(got, want) {
177			t.Errorf("descriptor bytes differ from BuildDescriptor with the previous hosts:\n got %s\nwant %s", got, want)
178		}
179		// B1: after an up, a seed keeps the node address and the URLs that depend on it.
180		prev := mustParseDescriptor(t, previous)
181		now := mustParseDescriptor(t, got)
182		if !reflect.DeepEqual(now.Hosts, previousHosts) {
183			t.Errorf("hosts after the seed = %v, want the hosts of the previous descriptor %v", now.Hosts, previousHosts)
184		}
185		if !reflect.DeepEqual(now.REST, prev.REST) || !reflect.DeepEqual(now.DockerConnectors, prev.DockerConnectors) {
186			t.Errorf("rest or dockerConnectors changed by the seed:\nbefore %+v %+v\nafter  %+v %+v", prev.REST, prev.DockerConnectors, now.REST, now.DockerConnectors)
187		}
188	
189		// Output: the lines of Seed (`seed: ...`) on stdout, the descriptor path.
190		if !strings.Contains(stdout, "seed: "+progressMarker) {
191			t.Errorf("stdout lost the `seed: ...` lines of Seed:\n%s", stdout)
192		}
193		if !strings.Contains(stdout, h.descriptor) {
194			t.Errorf("stdout does not say where the descriptor is (%s):\n%s", h.descriptor, stdout)
195		}
196		requireClean(t, stdout, stderr)
197	}
