216	// A failure at any step stops the seed, and the descriptor is written only after
217	// a Seed that succeeded: a partial SeedResult is never described.
218	func TestSeedDescriptorIsWrittenOnlyAfterASuccessfulSeed(t *testing.T) {
219		be := benchError()
220		skopeoMissing := &nexusbench.BenchError{Kind: nexusbench.SkopeoMissing, Cause: "skopeo was not found on PATH", Check: "install skopeo", Err: errors.New("exec: " + secretMarker)}
221		tests := []struct {
222			name      string
223			setup     func(h *harness)
224			wantText  string // the exact text of stderr, trimmed
225			notCalled []string
226		}{
227			{"seed fails", func(h *harness) {
228				h.seedErr = be
229				// Seed returns what it had put in place together with the error.
230				h.seedRes = nexusbench.SeedResult{Images: nexusbench.Dataset()[:2]}
231			}, be.Error(), nil},
232			{"seed fails with an error that is not a BenchError", func(h *harness) {
233				// NX-01 behavior of fail(): an error that is not a BenchError is
234				// printed as it is (it holds no secret here).
235				h.seedErr = errors.New("seed: the copy was interrupted")
236			}, "seed: the copy was interrupted", nil},
237			{"seed fails with a secret in the cause of a BenchError", func(h *harness) {
238				// The cause (Err) is never printed: requireClean applies.
239				h.seedErr = &nexusbench.BenchError{
240					Kind: nexusbench.SeedFailed, Cause: "a copy was refused", Check: "run the seed again",
241					Err: errors.New("skopeo said: " + secretMarker),
242				}
243			}, "", nil},
244			{"preflight fails", func(h *harness) { h.preflightErr = be }, be.Error(), []string{"seed"}},
245			{"skopeo is missing", func(h *harness) { h.newCopierErr = skopeoMissing }, skopeoMissing.Error(), []string{"preflight:OpSeed", "seed"}},
246			{"kubectl is missing", func(h *harness) {
247				h.newRunnerErr = &nexusbench.BenchError{Kind: nexusbench.KubectlMissing, Cause: "kubectl was not found on PATH", Check: "run `mise install`"}
248			}, "", []string{"preflight:OpSeed", "seed"}},
249			{"the forwarder cannot be built", func(h *harness) { h.newForwarderErr = be }, be.Error(), []string{"preflight:OpSeed", "seed"}},
250			{"the secrets path is refused", func(h *harness) {
251				h.newStoreErr = &nexusbench.BenchError{Cause: "the secrets path is in a repository and not ignored", Check: "set NEXUS_BENCH_SECRETS"}
252			}, "", []string{"preflight:OpSeed", "seed"}},
253		}
254		for _, tt := range tests {
255			t.Run(tt.name, func(t *testing.T) {
256				h := newHarness(t)
257				tt.setup(h)
258				before := h.writePreviousDescriptor()
259				code, stdout, stderr := h.run("seed")
260				if code != 1 {
261					t.Errorf("exit code = %d, want 1", code)
262				}
263				want := tt.wantText
264				var asBench *nexusbench.BenchError
265				if want == "" && errors.As(firstError(h), &asBench) {
266					want = asBench.Error()
267				}
268				if got := strings.TrimSpace(stderr); got != want {
269					t.Errorf("stderr = %q, want exactly %q", got, want)
270				}
271				requireClean(t, stdout, stderr)
272				for _, e := range tt.notCalled {
273					if h.has(e) {
274						t.Errorf("%s must not run after this failure, events: %v", e, h.eventList())
275					}
276				}
277				after, err := os.ReadFile(h.descriptor)
278				if err != nil || !bytes.Equal(before, after) {
279					t.Errorf("the descriptor of the previous run was changed (err=%v)", err)
280				}
281			})
282		}
283	}
